# Digitalizacija beležk SHS in Kraljevine Jugoslavije - Diplomsko delo# Nik Česenj Vodovnik, 04180450 - Upravna informatika# Študijsko leto 2022/2023# Datoteka folder.pyfrom .structure import Structurefrom .document import Documentclass Folder(Structure):    def __init__(self, name, path):        super().__init__(name, path)        self._num, self._meeting = self.parse_name()        self._documents: list[Document] = []    # PRINT OBJECT    def __str__(self):        return f"Ime mape:         {self._name}\n" \               f"Razpon sestankov: {self._num}\n" \               f"Vrsta sestanka:   {self._meeting}\n"    # PARSING METHOD    def parse_name(self) -> tuple[str, str]:        parsed = self.name.split("_")        return parsed[0], parsed[1]    @property    def num(self) -> str:        return self._num    @num.setter    def num(self, new_num: str) -> None:        self._num = new_num    @property    def meeting(self) -> str:        return self._meeting    @meeting.setter    def meeting(self, new_meeting):        self._meeting = new_meeting    @property    def documents(self) -> list[Document]:        return self._documents    @documents.setter    def documents(self, new_list: list[Document]) -> None:        self._documents = new_list    def add_document(self, new_document: Document) -> None:        self._documents.append(new_document)    def add_documents(self, new_documents: list[Document]) -> None:        self._documents += new_documents